declare namespace xr = "xrechnung";
declare namespace u = "undefined";
declare function xr:checkIBAN($iban as xs:string) as xs:boolean { let $normalizedIban := (normalize-space(replace($iban, '([\s])', ''))) return (matches($normalizedIban, ('^[A-Z]{2}[0-9]{2}[a-zA-Z0-9]{0,30}$')) and                           u:bigmod(string-join(for $cp in string-to-codepoints(concat(substring($normalizedIban,5),upper-case(substring($normalizedIban,1,2)),substring($normalizedIban,3,2))) return (if($cp > 64) then string($cp - 55) else string($cp - 48)),''), 97) = 1) };
declare function u:bigmod($digits as xs:string, $m as xs:integer) as xs:integer { fold-left(string-to-codepoints($digits), 0, function($acc, $c) { ($acc * 10 + $c - 48) mod $m }) };

